#pragma once
#include "storage/StorageEnvelope.hpp"
#include "content/Canonical.hpp"
#include "platform/ProfileAccessMac.hpp"
#include <map>
#include <set>
namespace fathom::storage {
// Purpose-specific immutable suite self-report. No captured Attempt is rewritten.
namespace suite {
using O=Value::Object;using A=Value::Array;
inline void need(bool b,const std::string& why){if(!b)throw EnvelopeError("SUITE_REVIEW_INVALID",why);}
inline const Value& f(const Value& v,const std::string& k){auto p=v.find(k);need(p,"Missing suite field "+k);return *p;}
inline std::string text(const Value& v){need(v.isString(),"Suite text required");return v.string();}
inline std::int64_t integer(const Value& v,std::int64_t minimum=0){std::int64_t n;need(v.integer(n)&&n>=minimum,"Suite integer required");return n;}
inline void fields(const Value& v,std::initializer_list<const char*> names){need(v.isObject()&&v.object().size()==names.size(),"Exact suite fields required");for(auto n:names)f(v,n);}
inline void score(const Value& v){need(v.null()||v==Value("Struggling")||v==Value("Developing")||v==Value("Clean")||v==Value("Easy"),"Explicit suite self-assessment required");}
inline void plan(const Value& v){fields(v,{"version","items"});need(integer(f(v,"version"),1)==1,"Unsupported suite plan");auto& items=f(v,"items");need(items.isArray()&&!items.array().empty()&&items.array().size()<=4096,"Suite plan capacity1..4096");std::set<std::string> keys,bindings;std::pair<std::int64_t,std::int64_t> previous{0,0};
 for(auto& i:items.array()){fields(i,{"source_exercise_key","index_revision","source_revision","level_key","sublevel_key","source_order","level_order","item_id","variant_id","content_revision","content_version","source_manifest_sha256","source_refs","source_binding"});for(auto k:{"source_exercise_key","index_revision","source_revision","level_key","sublevel_key","content_version","source_binding"})need(!text(f(i,k)).empty(),"Empty suite source annotation");auto ordering=std::make_pair(integer(f(i,"level_order"),1),integer(f(i,"source_order"),1));need(previous<ordering,"Suite plan must preserve positive reviewed source order");previous=ordering;O binding;for(auto k:{"item_id","variant_id","content_revision","content_version","source_manifest_sha256","source_refs","source_binding"})binding.emplace(k,f(i,k));need(bindings.insert(canonical(binding)).second,"Ambiguous duplicate suite source binding");integer(f(i,"content_revision"),1);need(keys.insert(text(f(i,"source_exercise_key"))).second,"Duplicate suite source exercise");auto refs=f(i,"source_refs");need(refs.isArray()&&!refs.array().empty(),"Suite source refs required");for(auto& r:refs.array())need(!text(r).empty(),"Empty suite source ref");auto manifest=text(f(i,"source_manifest_sha256"));need(manifest.size()==64&&manifest.find_first_not_of("0123456789abcdef")==std::string::npos,"Suite manifestSHA required");}
}
inline const Value& matchingItem(const Value& p,const Envelope& e){plan(p);need(e.kind=="Attempt"&&e.outcome=="complete"&&e.active.numerator()>0,"Only positive completed Attempts can enter suite");auto& c=f(e.value,"context");auto& r=f(e.value,"result");need(f(r,"outcome")==Value("natural")&&f(r,"assessment").null(),"Suite member must have natural termination and null original assessment");auto target=c.find("target");need(target&&target->find("cycles")&&f(r,"completed_cycles").array().size()>=static_cast<std::size_t>(integer(f(*target,"cycles"),1)),"Natural target not reached");
 std::set<std::string> cycles,full;for(auto& id:f(r,"completed_cycles").array())need(cycles.insert(canonical(id)).second,"Duplicate completed cycle");auto& span=f(c,"span");need(span.find("start")&&span.find("end"),"Suite requires exact captured span");for(auto& traversal:f(r,"traversals").array())if(f(traversal,"status")==Value("complete")){need(f(traversal,"start")==f(span,"start")&&f(traversal,"end")==f(span,"end"),"Completed traversal differs from exact span");need(full.insert(canonical(f(traversal,"cycle"))).second,"Duplicate complete traversal");}need(!cycles.empty()&&cycles==full,"Natural target lacks complete traversal proof");
 const Value* found=nullptr;for(auto& i:f(p,"items").array()){bool same=true;for(auto k:{"item_id","variant_id","content_revision","content_version","source_manifest_sha256","source_refs"})same= same&&(f(i,k)==f(c,k));same=same&&(f(i,"source_binding")==f(f(c,"configuration"),"source_binding"));if(same){need(!found,"Ambiguous source plan member");found=&i;}}need(found,"Attempt source is not in frozen suite");return *found;
}
inline std::string unhex(const Value& v){auto s=text(f(v,"blob_hex"));need(s.size()%2==0&&s.find_first_not_of("0123456789abcdef")==std::string::npos,"Invalid suite blob");std::string b;for(std::size_t i=0;i<s.size();i+=2)b.push_back(static_cast<char>(std::stoi(s.substr(i,2),nullptr,16)));return b;}
// Validate complete typed suite rows against original finalized envelopes. Shared
// by writer inspection and consumers; source contexts/digests are authoritative.
inline Value projection(const Value& authority){O suites,assessments;auto table=authority.find("suite_fact");if(!table)return O{{"version",Value::fromInteger(1)},{"suites",suites},{"assessments",assessments}};need(table->isArray(),"Suite table required");std::map<std::string,Envelope> finals;std::map<std::string,std::int64_t> finalSequences;for(auto& row:f(authority,"finalized").array()){auto e=validateEnvelope(unhex(row.array().at(1)));finalSequences.emplace(e.owner,integer(row.array().at(3),1));finals.emplace(e.owner,std::move(e));}
 std::map<std::string,Value> plans,members,reviews;std::map<std::string,std::int64_t> sequences;std::set<std::string> operations,ids;std::map<std::string,std::string> attemptSuites;
 for(auto& row:table->array()){need(row.isArray()&&row.array().size()==8,"Suite rowshape8 required");auto& a=row.array();auto id=text(a[0]),suiteId=text(a[1]),kind=text(a[2]),op=text(a[3]);validateUuid(id);validateUuid(suiteId);need(ids.insert(id).second&&operations.insert(op).second&&!op.empty(),"Duplicate suite fact/operation");auto payload=parseCanonical(unhex(a[5]));need(content::sha256(canonical(payload))==text(a[6]),"Suite payload digest mismatch");validateUtc(text(a[4]));sequences.emplace(id,integer(a[7],1));
 if(kind=="definition"){fields(payload,{"suite_id","created_utc","plan"});need(id==suiteId&&f(payload,"suite_id")==a[1]&&f(payload,"created_utc")==a[4]&&plans.emplace(suiteId,payload).second,"Conflicting suite definition");plan(f(payload,"plan"));}
 else if(kind=="member"){fields(payload,{"suite_id","attempt_id","completed_utc","context","envelope_sha256","source_exercise_key"});need(f(payload,"suite_id")==a[1]&&f(payload,"completed_utc")==a[4],"Suite member summaries differ");auto owner=text(f(payload,"attempt_id"));need(attemptSuites.emplace(owner,suiteId).second,"Attempt already has suite membership");members.emplace(id,payload);}
 else if(kind=="review"){fields(payload,{"suite_id","reviewed_utc","score","members","disposition"});score(f(payload,"score"));need(f(payload,"suite_id")==a[1]&&f(payload,"reviewed_utc")==a[4]&&reviews.emplace(suiteId,payload).second,"Conflicting suite review");}else need(false,"Unknown suite factkind");
 }
 for(auto& kv:plans)suites.emplace(kv.first,O{{"suite_id",kv.first},{"plan",f(kv.second,"plan")},{"members",A{}},{"review",nullptr},{"closed",false}});
 for(auto& kv:members){auto& m=kv.second;auto sid=text(f(m,"suite_id")),owner=text(f(m,"attempt_id"));need(plans.count(sid)&&finals.count(owner),"Unknown suite/member authority");auto& e=finals.at(owner);auto& item=matchingItem(f(plans.at(sid),"plan"),e);need(sequences.at(kv.first)>sequences.at(sid),"Member precedes definition");need(sequences.at(kv.first)>finalSequences.at(owner),"Member precedes finalized Attempt");bool sessionBound=false;for(auto& sr:f(authority,"session").array())if(sr.array()[0]==f(f(e.value,"context"),"session_id")){auto planRef=sr.array()[4];need(!planRef.null(),"Suite Session plan missing");auto sv=parseCanonical(unhex(planRef));need(f(sv,"suite_id")==Value(sid),"Attempt Session belongs to another suite");sessionBound=true;}need(sessionBound,"Unknown suite Session");need(f(m,"context")==f(e.value,"context")&&f(m,"envelope_sha256")==Value(e.digest)&&f(m,"source_exercise_key")==f(item,"source_exercise_key"),"Frozen suite member source/digest mismatch");need(!utcBefore(e.practiceUtc,text(f(plans.at(sid),"created_utc"))),"Attempt predates suite definition");need(!utcBefore(text(f(m,"completed_utc")),e.practiceUtc),"Suite membership predates Attempt");for(auto& other:suites.at(sid).object().at("members").array())need(f(other,"source_exercise_key")!=f(m,"source_exercise_key"),"Conflicting attempts for one suite exercise");suites.at(sid).object().at("members").array().push_back(m);}
 for(auto& kv:reviews){need(suites.count(kv.first),"Review lacks suite definition");std::int64_t reviewSeq=0;for(auto& row:table->array())if(row.array()[1]==Value(kv.first)&&row.array()[2]==Value("review"))reviewSeq=integer(row.array()[7],1);need(reviewSeq>sequences.at(kv.first),"Review precedes definition");need(!utcBefore(text(f(kv.second,"reviewed_utc")),text(f(plans.at(kv.first),"created_utc"))),"Review timestamp precedes suite definition");for(auto& member:members)if(f(member.second,"suite_id")==Value(kv.first))need(sequences.at(member.first)<reviewSeq,"Member inserted after frozen review");auto& view=suites.at(kv.first);auto listed=f(kv.second,"members");need(listed.isArray(),"Review requires frozen membership");need(!listed.array().empty()||f(kv.second,"score").null(),"Cannot score empty suite");auto disposition=listed.array().empty()?"unplayed_closed_without_assessment":f(kv.second,"score").null()?"closed_without_assessment":"shared_suite_self_assessment";need(f(kv.second,"disposition")==Value(disposition),"Review disposition differs from actual membership/score");std::set<std::string> expected,actual;for(auto& m:view.object().at("members").array()){auto owner=text(f(m,"attempt_id"));expected.insert(owner);need(!utcBefore(text(f(kv.second,"reviewed_utc")),text(f(m,"completed_utc"))),"Review predates member");assessments.emplace(owner,O{{"suite_id",kv.first},{"score",f(kv.second,"score")},{"reviewed_utc",f(kv.second,"reviewed_utc")},{"provenance","deferred suite self-assessment"}});}for(auto& owner:listed.array())need(actual.insert(text(owner)).second,"Duplicate review owner");need(expected==actual,"Review membership is not atomic frozen membership");view.object().at("review")=kv.second;view.object().at("closed")=true;}
 return O{{"version",Value::fromInteger(1)},{"suites",suites},{"assessments",assessments}};
}
} // namespace suite
} // namespace fathom::storage
